/**
 * Sorteia uma palavra de tamanho entre `min` e `max`, do vocabulário escolhido, evitando as iniciais em uso.
 * Mantém uma fila embaralhada por tamanho: uma palavra só repete quando as do mesmo tamanho se esgotam.
 */
export class WordBank {
    private queues: Record<number, string[]> = {};
    private bank: Record<number, string[]>;

    constructor(vocab: Vocabulary = 'misto') {
        this.bank = BANKS[vocab] ?? BANKS.misto;
    }

    pick(min: number, max: number, usedInitials: Set<string>) {
        const lengths: number[] = [];
        for (let len = min; len <= max; len++) if (this.bank[len]?.length) lengths.push(len);
        if (!lengths.length) return 'bug';
        // Tenta algumas vezes achar uma inicial livre; cada tentativa sorteia um tamanho da faixa.
        for (let attempt = 0; attempt < 12; attempt++) {
            const len = lengths[Math.floor(Math.random() * lengths.length)]!;
            const queue = this.queues[len] ?? (this.queues[len] = this.shuffle(this.bank[len]!));
            const word = queue.pop() ?? (this.queues[len] = this.shuffle(this.bank[len]!)).pop()!;
            if (!usedInitials.has(word[0]!)) return word;
            // Volta para o fim da fila e tenta outra.
            queue.unshift(word);
        }
        return lengths.includes(min) ? (this.bank[min]![0] ?? 'bug') : 'bug';
    }

    private shuffle(list: string[]) {
        const copy = [...list];
        for (let i = copy.length - 1; i > 0; i--) {
            const j = Math.floor(Math.random() * (i + 1));
            [copy[i], copy[j]] = [copy[j]!, copy[i]!];
        }
        return copy;
    }
}
